Here's a Python program that meets your requirements. This program uses a dictionary to store student names as keys and their corresponding grades as values. It allows users to add, remove, and update student grades, as well as calculate the average grade of all students and display the grades of a specific student.

```python
# Initialize an empty dictionary to store student information
student_grades = {}

def add_student(name, grade):
    """Add a student with a given name and grade to the dictionary."""
    if name in student_grades:
        print(f"{name} already exists in the dictionary. Grade updated.")
    else:
        student_grades[name] = grade
        print(f"{name} added with grade {grade}.")

def remove_student(name):
    """Remove a student with a given name from the dictionary."""
    if name in student_grades:
        del student_grades[name]
        print(f"{name} removed from the dictionary.")
    else:
        print(f"{name} does not exist in the dictionary.")

def update_student(name, new_grade):
    """Update a student's grade in the dictionary."""
    if name in student_grades:
        student_grades[name] = new_grade
        print(f"{name}'s grade updated to {new_grade}.")
    else:
        print(f"{name} does not exist in the dictionary.")

def calculate_average():
    """Calculate the average grade of all students in the dictionary."""
    if student_grades:
        total_grade = sum(student_grades.values())
        num_students = len(student_grades)
        avg_grade = total_grade / num_students
        print(f"Average grade: {avg_grade:.2f}")
    else:
        print("No students have been added yet.")

def display_student(name):
    """Display the grade of a specific student in the dictionary."""
    if name in student_grades:
        print(f"{name}'s grade: {student_grades[name]}")
    else:
        print(f"{name} does not exist in the dictionary.")

# Function calls for sample input
add_student("John", 90)
add_student("Jane", 85)
remove_student("John")
update_student("Jane", 95)
calculate_average()
display_student("Jane")
```

This program will output the sample output you provided. You can modify the sample input to test the program further.
